	import re

#	log = system.util.getLogger('kanoaSecurity')
#	log.trace("%s"%dict(self.session.custom.kanoa.security['userCRUD']))		

	if not  value['auth']['authenticated']: return 'Click to log in'
	user = value['auth']['user']	
	userLabel = "%s %s"%(user['firstName'], user['lastName']) if user['firstName'] and user['lastName'] else user['userName']

	userCRUD = dict(value['sessionSecurity']['userCRUD'])
	info = []

	def prettify(name):
		return re.sub(r'(?<!^)(?=[A-Z])', ' ', name).title()

	for k, v in userCRUD.items():
		if k == 'isGatewayAdmin':
			if v: info.append(prettify(k))
		elif hasattr(v, 'get') and v.get('enabled'): info.append(prettify(k))

	return "%s %s"%(userLabel, ', '.join(info))

